package com.srm.inventory.service;
import com.srm.inventory.dto.*; import com.srm.inventory.entity.*; import com.srm.inventory.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class OrderService { private final OrderRepository orders; private final ProductRepository products; public OrderService(OrderRepository o,ProductRepository p){orders=o;products=p;} public List<CustomerOrder> list(OrderStatus status){return status==null?orders.findAll():orders.findByStatus(status);} public CustomerOrder get(Long id){return orders.findById(id).orElseThrow(()->new NoSuchElementException("Order not found"));} @Transactional public CustomerOrder create(OrderRequest r){ CustomerOrder order=new CustomerOrder(); order.setCustomerName(r.customerName()); order.setCustomerEmail(r.customerEmail()); order.setPhoneNumber(r.phoneNumber()); order.setRoomNumber(r.roomNumber()); order.setHostelBlock(r.hostelBlock()); order.setDeliveryNote(r.deliveryNote()); order.setTransactionReference(r.transactionReference()); order.setPaymentMethod(r.paymentMethod()); order.setPaymentStatus(r.paymentMethod()==PaymentMethod.QR_PAYMENT?PaymentStatus.PAYMENT_SUBMITTED:PaymentStatus.CASH_PENDING); for(var requested:r.items()){ Product p=products.findById(requested.productId()).orElseThrow(()->new NoSuchElementException("Product not found: "+requested.productId())); if(p.getStockQuantity()<requested.quantity()) throw new IllegalArgumentException("Insufficient stock for "+p.getName()); OrderItem item=new OrderItem(); item.setOrder(order); item.setProduct(p); item.setQuantity(requested.quantity()); item.setUnitPrice(p.getPrice()); item.setUnitCost(p.getCostPrice()); order.getItems().add(item); } return orders.save(order); } @Transactional public CustomerOrder updateStatus(Long id,StatusRequest r){ CustomerOrder o=get(id); if(o.getStatus()==OrderStatus.CANCELLED || o.getStatus()==OrderStatus.DELIVERED) throw new IllegalArgumentException("A completed or cancelled order cannot be changed"); if(!allowed(o.getStatus(),r.status())) throw new IllegalArgumentException("Use the next dispatch step shown in the admin portal"); if(r.status()==OrderStatus.CONFIRMED && o.getPaymentStatus()!=PaymentStatus.PAYMENT_VERIFIED && o.getPaymentStatus()!=PaymentStatus.CASH_COLLECTED) throw new IllegalArgumentException("Verify QR payment or collect cash before confirming this order"); if(r.status()==OrderStatus.CONFIRMED){for(OrderItem i:o.getItems()){Product p=i.getProduct();if(p.getStockQuantity()<i.getQuantity())throw new IllegalArgumentException("Insufficient stock for "+p.getName());p.setStockQuantity(p.getStockQuantity()-i.getQuantity());}} if(r.status()==OrderStatus.CANCELLED && o.getStatus()!=OrderStatus.PENDING){for(OrderItem i:o.getItems()){Product p=i.getProduct();p.setStockQuantity(p.getStockQuantity()+i.getQuantity());}} o.setStatus(r.status()); return orders.save(o); } private boolean allowed(OrderStatus from,OrderStatus to){if(to==OrderStatus.CANCELLED)return from!=OrderStatus.DELIVERED; return (from==OrderStatus.PENDING&&to==OrderStatus.CONFIRMED)||(from==OrderStatus.CONFIRMED&&to==OrderStatus.PREPARING)||(from==OrderStatus.PREPARING&&to==OrderStatus.OUT_FOR_DELIVERY)||(from==OrderStatus.OUT_FOR_DELIVERY&&to==OrderStatus.DELIVERED);} @Transactional public CustomerOrder updatePayment(Long id,PaymentRequest r){ CustomerOrder o=get(id); if(o.getStatus()!=OrderStatus.PENDING) throw new IllegalArgumentException("Payment can only be updated while an order is pending"); if(o.getPaymentMethod()==PaymentMethod.QR_PAYMENT&&r.paymentStatus()!=PaymentStatus.PAYMENT_VERIFIED) throw new IllegalArgumentException("QR orders must be marked Payment Verified"); if(o.getPaymentMethod()==PaymentMethod.CASH_ON_DELIVERY&&r.paymentStatus()!=PaymentStatus.CASH_COLLECTED) throw new IllegalArgumentException("Cash orders must be marked Cash Collected"); o.setPaymentStatus(r.paymentStatus()); return orders.save(o); } @Transactional public void delete(Long id){CustomerOrder o=get(id); if(o.getStatus()!=OrderStatus.PENDING) throw new IllegalArgumentException("Only pending orders can be deleted"); orders.delete(o);} }
